From a088bb9e49076c0708c217b9572d70d4d3b8f18b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:10:04 +0100
Subject: [PATCH] wallpapers/image: reload the wallpaper when its file is
 overwritten

Only newly created files were noticed, so writing new content to the
image already used as wallpaper kept showing the old picture until a
restart. React to in-place changes too, and skip half-written files.

BUG: 506862
---
 .../imagepackage/contents/ui/ImageStackView.qml   | 15 +++++++++++++--
 wallpapers/image/plugin/utils/mediaproxy.cpp      |  1 +
 2 files changed, 14 insertions(+), 2 deletions(-)

diff --git a/wallpapers/image/imagepackage/contents/ui/ImageStackView.qml b/wallpapers/image/imagepackage/contents/ui/ImageStackView.qml
index 4b80741263..49a7bedefc 100644
--- a/wallpapers/image/imagepackage/contents/ui/ImageStackView.qml
+++ b/wallpapers/image/imagepackage/contents/ui/ImageStackView.qml
@@ -31,6 +31,7 @@ QQC2.StackView {
      * @see BUG 456189
      */
     property Item pendingImage
+    property bool pendingKeepsCurrentOnError: false

     property bool doesSkipAnimation: true

@@ -73,7 +74,7 @@ QQC2.StackView {
         loadImage(true);
     }

-    function loadImage(skipAnimation) {
+    function loadImage(skipAnimation, keepCurrentOnError) {
         if (pendingImage) {
             pendingImage.statusChanged.disconnect(replaceWhenLoaded);
             pendingImage.destroy();
@@ -106,6 +107,7 @@ QQC2.StackView {
             properties.forceImageAnimation = view.forceImageAnimation;
         }
         pendingImage = baseImage.createObject(view, properties);
+        pendingKeepsCurrentOnError = !!keepCurrentOnError;

         if (!pendingImage) {
             console.warn(baseImage.errorString());
@@ -123,6 +125,15 @@ QQC2.StackView {
         }

         pendingImage.statusChanged.disconnect(replaceWhenLoaded);
+
+        // The file may still be being written, so wait for its next change
+        if (pendingImage.status === Image.Error && pendingKeepsCurrentOnError && view.currentItem) {
+            pendingImage.destroy();
+            pendingImage = null;
+            wallpaperInterface.loading = false;
+            return;
+        }
+
         // BUG 454908: Update accent color
         pendingImage.QQC2.StackView.onActivated.connect(() => {
             if (Qt.colorEqual(mediaProxy.customColor, "transparent") && Qt.colorEqual(wallpaperInterface.accentColor, "transparent")) {
@@ -176,6 +187,6 @@ QQC2.StackView {

         onActualSizeChanged: Qt.callLater(view.loadImageImmediately);
         onColorSchemeChanged: view.loadImageImmediately();
-        onSourceFileUpdated: view.loadImageImmediately()
+        onSourceFileUpdated: view.loadImage(true, true)
     }
 }
diff --git a/wallpapers/image/plugin/utils/mediaproxy.cpp b/wallpapers/image/plugin/utils/mediaproxy.cpp
index f726041944..4ade357381 100644
--- a/wallpapers/image/plugin/utils/mediaproxy.cpp
+++ b/wallpapers/image/plugin/utils/mediaproxy.cpp
@@ -40,6 +40,7 @@ MediaProxy::MediaProxy(QObject *parent)
     , m_isDarkColorScheme(isDarkColorScheme(s_theme->palette()))
 {
     connect(&m_dirWatch, &KDirWatch::created, this, &MediaProxy::slotSourceFileUpdated);
+    connect(&m_dirWatch, &KDirWatch::dirty, this, &MediaProxy::slotSourceFileUpdated);
 }

 void MediaProxy::classBegin()
-- 
